{
  "findings": [
    {
      "check_id": "CKV_AWS_3",
      "title": "Ensure all data stored in the EBS is securely encrypted",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "HIGH",
      "explanation": "The EBS volume has encryption explicitly disabled (encrypted = false), leaving any data stored on it vulnerable to unauthorized access if the underlying physical media is compromised or accessed via snapshot sharing."
    },
    {
      "check_id": "CKV_AWS_189",
      "title": "Ensure EBS Volume is encrypted by KMS using a customer managed Key (CMK)",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "Even if encryption were enabled, the resource does not specify a kms_key_id, meaning it would default to AWS-managed keys. Using Customer Managed Keys (CMK) provides better control over key rotation and access policies."
    }
  ],
  "patched_code": "resource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n  # Note: For CKV_AWS_189 compliance, you should also add 'kms_key_id' referencing a CMK.\n  # Example: kms_key_id = aws_kms_key.example.id\n}\n",
  "fix_summary": "Enabled encryption for the EBS volume by setting 'encrypted' to true to remediate CKV_AWS_3. Added a comment advising the addition of 'kms_key_id' to satisfy CKV_AWS_189 requirements for Customer Managed Keys, as no KMS key resource was defined in the provided snippet."
}
